<?php require '../config.php';need_admin();if($_SERVER['REQUEST_METHOD']!=='POST')exit('Invalid');check_csrf();$id=(int)$_POST['id'];$status=$_POST['status']??'under_review';$allowed=['under_review','planned','in_progress','shipped','declined'];if(!in_array($status,$allowed,true))exit('Invalid status');$r=trim($_POST['response']??'');$s=db()->prepare('UPDATE features SET status=?,admin_response=? WHERE id=?');$s->execute([$status,$r,$id]);flash('Feature request updated.');header('Location:view.php?id='.$id);
